{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, s.service_name callee, s.span_name callee_span, s.attr_http_response_status_code sc, s.attr_status_code, count(*) n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "806 preserve POST calls to seat arrive as 'GET /error' and return HTTP 405, while the normal POST to seats path is absent."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, left(message,120) msg, count(*) c FROM abnormal_logs WHERE service_name IN ('ts-seat-service','ts-preserve-service') AND level IN ('WARN','SEVERE') GROUP BY ALL ORDER BY c DESC",
          "claim": "Seat logs 806 HttpRequestMethodNotSupported warnings; preserve logs 806 SEVERE dispatcher exceptions."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code sc, attr_status_code, count(*) n, round(avg(duration)/1e6,1) ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Preserve's server span for POST /preserve returns status Error/500 on 806 of 807 requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, s.service_name callee, s.attr_http_response_status_code sc, s.attr_status_code, count(*) n, round(avg(c.duration)/1e6,1) client_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.span_name LIKE '%preserve%' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Requests to ui-dashboard's POST /preserve path return 500 errors (37 cases) and 503 (1), with 20s client timeouts."
        }
      ]
    }
  ]
}
